;Старейшина ХеворHV_SM=-HV_+PL        DW H0+SM,H1+SM,H2+SM,H3+SM,H4+SM,H5+SM,H6+SM,H7+SM        DW H8+SM,H9+SM        DW H10+SM,H11+SM,H12+SM,H13+SM,H14+SM,H15+SM,H16+SM        DW H17+SMH0      DB "Вам случайно это не нужно?",SOBES        DB "А что это? Не, не надо... Я бы",CR        DB "попросил...",ENDH1      DB "Здравствуйте, дедушка.",CR        DB "Расскажите, что у вас тут",CR        DB "случилось?",SOBES        DB "Какой я тебе дедушка, подруга!",CR        DB "Я - Хевор. Старейшина. А ты кто",CR        DB "такая? Чего тут вынюхиваешь?",HERO        DB "Не валяйте дурака, Хевор! Это же",CR        DB "я, Вера.",SOBES        DB "Какая Вера? Колдунья? Непохожа!",HERO;           123456789-123456789-123456789-123        DB "Непохожа?! Ну и сидите тут,",CR        DB "бедствуйте...",SOBES        DB "Постой! Настроение у меня плохое.",CR        DB "К тому же, я вас действительно",CR        DB "не узнаю... Может намекнете чем?",HERO        DB "Вам паспорт показать что ли?",SOBES        DB "Валяй.",HERO        DB "Выдавали бы их еще колдуньям...",DIALOG,2H2      DB "Мне все еще нужно доказывать, что",CR        DB "я Вера?",SOBES        DB "Непременно!",ENDH3      DB "Знакомый почерк?",SOBES        DB "Да, это мое письмо. Так значит,",CR        DB "вы и есть Вера! Простите, давно",CR        DB "вас не видел, поэтому не признал.",HERO        DB "Рассказывайте, что случилось?",SOBES        DB "Кто-то зло на нас держит. Строит",CR        DB "пакости всякие: одни вещи",CR        DB "пропадают, другие появляются,"        DB NEXT        DB "а остальные ведут себя совсем",CR        DB "не так, как обычно. И вообще -",CR        DB "посмотрите вокруг! Даже фонтан"        DB NEXT        DB "пересох...",HERO        DB "Кто ж вас так невзлюбил?",SOBES        DB "Не знаю. Никто его не видел...",CR        DB "Да и вообще, вроде кроме меня",CR        DB "никто ничего плохого не замечает.",HERO        DB "Может все-таки видел кто? Или",CR        DB "вдруг знает?",SOBES        DB "Может Провидец знает?",HERO        DB "Кто такой?",SOBES        DB "Странный человек. Глебом зовут.",CR        DB "Видит разное... Иногда хорошее,",CR        DB "иногда плохое. В общем, странный"        DB NEXT        DB "он... Хотя, вроде, не злой.",HERO        DB "Правда не злой? Он сам не мог",CR        DB "такого натворить?",SOBES        DB "Не знаю... Спроси у него сама.",HERO        DB "А где его найти?",SOBES        DB "Где-то... Я же говорю, странный",CR        DB "он...",HERO        DB "Ладно. Пойду поищу.",SCRPT,59H4      DB 5,67,"Ну, где этот ваш Глеб?",SOBES        DB "Ох, не знаю...",ENDH5      DB "Глеб говорит, что колдун Зловет",CR        DB "здесь безобразничает... Надо его",CR        DB "найти и побеседовать по душам.",SOBES        DB "Колдун? Ох, и страшно мне!",HERO        DB "Не бойтесь, старейшина! Вы должны",CR        DB "быть примером для всех жителей!",CR        DB "И не таких колдунов в Морию"        DB NEXT        DB "сбрасывали! Пойду искать нахала.",SOBES        DB "Не торопись, уважь сначала",CR        DB "старика. Тоскливо мне очень.",CR        DB "Раньше хоть фонтан журчал -"        DB NEXT        DB "настроение подымал. ""Оживи""",CR        DB "его, пожалуйста! Вот, у меня",CR        DB "ведро есть...",SCRPT,8H6      DB "Дорогой Хевор, вы не подскажете,",CR        DB "как мне ""оживить"" фонтан?",SOBES        DB "А вы точно волшебница? Мы его",CR        DB "и безо всякого волшебства",CR        DB "запускали...",ENDH7      DB "Слышите? Вода журчит!",SOBES        DB "Благодарю тебя, Вера. Возьми эту",CR        DB "штуку, она притягивает к себе",CR        DB "ложки, вилки и даже ножи! Вещь"        DB NEXT        DB "явно магическая. Боюсь ее у себя",CR        DB "держать...",SCRPT,12H8      DB "Как дела, Хевор?",SOBES        DB "Да ничего, помаленьку.",ENDH9      DB "Послушайте, Хевор, вы не знаете,",CR        DB "как собрать пшеницу и хмель?",SOBES        DB "Косой! Или серпом... Можно даже",CR        DB "ножиком, если изловчиться...",HERO        DB "А вы не подскажете, где найти",CR        DB "что-нибудь острое?",SOBES        DB "Серп-то у меня есть, но я уже",CR        DB "слаб и храню его для защиты. Мне",CR        DB "бы Амулет Здоровья... Я б никого"        DB NEXT        DB "не боялся!",SCRPT,33H10     DB "Как настроение, Хевор?",SOBES        DB "Страшно...",ENDH11     DB "Я нашла Амулет. Возьмите его,",CR        DB "Хевор.",SOBES        DB "Ой, спасибо! Как и обещал, даю",CR        DB "тебе серп. Только предупреждаю,",CR        DB "он несколько туповат.",SCRPT,15H12     DB "Хевор, вы не подскажете, каким",CR        DB "образом можно уничтожить Зловета?",SOBES        DB "Всякая нечисть боится огня! Это я",CR        DB "в одной книжке у Буквина читал.",SCRPT,51H13     DB "Хевор, вы меня видите?",SOBES        DB "А? Сгинь, нечисть! У меня Амулет",CR        DB "есть!",ENDH14     DB "Раз у вас нет зубов, возьмите",CR        DB "этот протез, и вы снова сможете",CR        DB "кушать.",SOBES        DB "Ну, Фёкла! Передай ей, что при",CR        DB "встрече я ей уши надеру... И всё",CR        DB "остальное тоже!",SCRPT,43H15     DB "Возьмите, мне не жалко.",SOBES        DB "Меня не напугаешь! Я с Амулетом!",ENDH16     DB "Хевор, я сожгла Зловета. Что",CR        DB "теперь?",SOBES        DB "Чую, какие-то силы здесь витают.",CR        DB "Ты везде хорошо смотрела?",HERO        DB "Да вроде ничего такого не видала.",SOBES        DB "Ищи лучше, должно быть!",ENDH17     DB "Ну видела я Глеба и что?",SOBES        DB "А ты говорила с ним?",ENDHEND